def has_dead_workers(self):

    # [<WorkerProcess(WorkerProcess-2, stopped[SIGKILL])>,
    # <WorkerProcess(WorkerProcess-2, stopped[SIGTERM])>

    defunct = False
    for x in self._workers:
        if getattr(x, 'exitcode', None):
            defunct = True
    return defunct

